class Refuse(Exception):
    pass


def read_lf(rel):
    path = ROOT / rel
    if not path.is_file():
        raise Refuse("ERROR: %s not found. Run this from the orrery folder."
                     % rel)
    raw = path.read_bytes()
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        raise Refuse("ERROR: %s is not UTF-8." % rel)
    return text.replace('\r\n', '\n'), '\r\n' in text


def md5(text):
    return hashlib.md5(text.encode('utf-8')).hexdigest()


def main():
    print("patch_L414_1 -- built on orrery %s\n" % BASE_SHA)
    out = {}
    try:
        for rel in NEW_FILES:
            if (ROOT / rel).exists():
                raise Refuse("ERROR: %s already exists, so this patch has "
                             "already run." % rel)
        src = {}
        for rel in EDITS:
            src[rel], crlf = read_lf(rel)
            if crlf:
                print("note: %s was CRLF in the working copy; it is written "
                      "LF" % rel)
        if 'def row_comment_indices' in src['provenance_scanner.py']:
            raise Refuse("ERROR: provenance_scanner.py already reads the row "
                         "run, so this patch has already run.")
        for rel, want in BASE_MD5.items():
            if md5(src[rel]) != want:
                raise Refuse("ERROR: %s is not the version this patch was "
                             "built against (orrery %s)." % (rel, BASE_SHA))
        print("ok  base: %d files match orrery %s"
              % (len(BASE_MD5), BASE_SHA))
        print("ok  the ledger, Where We Are, the protocol and the history "
              "files are checked at the lines edited")
        print()
        for rel, edits in EDITS.items():
            text = src[rel] + '\n'
            # Bottom-up: each edit leaves the lines above it unmoved.
            for label, old, new in reversed(edits):
                n = text.count(old)
                if n != 1:
                    raise Refuse("ANCHOR FAIL: %s: %s: expected 1 match, "
                                 "found %d." % (rel, label, n))
                text = text.replace(old, new)
                print("ok  %-48s %s" % (rel, label))
            out[rel] = text[:-1]
        out.update(NEW_FILES)
        for rel in NEW_FILES:
            print("ok  %-48s (new)" % rel)
        for rel, text in out.items():
            bad = sum(1 for ch in text if ord(ch) > 127)
            if bad and rel in NEW_FILES:
                raise Refuse("ERROR: %s would carry %d non-ASCII "
                             "character(s)." % (rel, bad))
    except Refuse as exc:
        print("\n%s\nNOTHING was written." % exc)
        sys.exit(1)

    for rel, text in out.items():
        path = ROOT / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        with open(path, 'w', encoding='utf-8', newline='') as f:
            f.write(text)
    print("\npatch applied: %d files written:" % len(out))
    for rel in out:
        print("  %s" % rel)

    print("\nskills_index.py -- writes the read plan and the manifest row:\n")
    r = subprocess.run([sys.executable, 'skills_index.py',
                        'PROJECT_INSTRUCTIONS.md'], cwd=ROOT,
                       capture_output=True, text=True)
    print(r.stdout + r.stderr)
    print("skills_index.py --check:\n")
    r2 = subprocess.run([sys.executable, 'skills_index.py', '--check'],
                        cwd=ROOT, capture_output=True, text=True)
    print(r2.stdout + r2.stderr)
    if r.returncode or r2.returncode:
        print("skills_index.py reported a problem, above. The files are "
              "written; tell Claude what it printed.\nUndo is Discard "
              "Changes in GitHub Desktop.")
        sys.exit(1)
    print(NEXT_STEPS)


